package com.sarathi.geckotest;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.KeyStore;import org.json.JSONObject;
/** Per-applicant Telegram credentials encrypted with an applicant-specific Android Keystore key. */
final class SecureSettings {
 private static String alias(int profile){if(profile<1||profile>9)throw new IllegalArgumentException("Invalid applicant");return profile==1?"mparivahan-config":"mparivahan-config-"+profile;}
 private static javax.crypto.SecretKey key(int profile)throws Exception{String alias=alias(profile);KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(alias)){KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return (javax.crypto.SecretKey)store.getKey(alias,null);}
 private static String prefKey(int profile){return "config_"+profile;}
 static synchronized JSONObject read(Context c,int profile)throws Exception{String saved=c.getSharedPreferences("secure",0).getString(prefKey(profile),"");if(saved.isEmpty()&&profile==1){saved=c.getSharedPreferences("secure",0).getString("config","");if(!saved.isEmpty())c.getSharedPreferences("secure",0).edit().putString(prefKey(1),saved).commit();}if(saved.isEmpty())return new JSONObject();String[] fields=saved.split(":",2);if(fields.length!=2)throw new IllegalStateException("Saved Telegram settings are invalid");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(profile),new GCMParameterSpec(128,Base64.decode(fields[0],Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(fields[1],Base64.NO_WRAP)),java.nio.charset.StandardCharsets.UTF_8));}
 static synchronized void write(Context c,int profile,JSONObject values)throws Exception{JSONObject merged=read(c,profile);for(String k:new String[]{"botToken","chatId","chatId2"})if(values.has(k))merged.put(k,values.getString(k));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(profile));String data=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(merged.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!c.getSharedPreferences("secure",0).edit().putString(prefKey(profile),data).commit())throw new IllegalStateException("Could not save Telegram settings");}
}